def semver_sort(versions):
    def parse(v):
        core = v.split('+', 1)[0]
        if '-' in core:
            main, pre = core.split('-', 1)
        else:
            main, pre = core, None
        major, minor, patch = (int(x) for x in main.split('.'))
        return (major, minor, patch, pre)

    def pre_key(pre):
        if pre is None:
            return None
        ids = pre.split('.')
        key = []
        for ident in ids:
            if ident.isdigit():
                key.append((0, int(ident), ''))
            else:
                key.append((1, 0, ident))
        return key

    class Wrapper:
        __slots__ = ('v', 'p')
        def __init__(self, v):
            self.v = v
            m, n, pa, pre = parse(v)
            self.p = (m, n, pa, pre)

        def __lt__(self, other):
            m1, n1, p1, pre1 = self.p
            m2, n2, p2, pre2 = other.p
            if (m1, n1, p1) != (m2, n2, p2):
                return (m1, n1, p1) < (m2, n2, p2)
            if pre1 is None and pre2 is None:
                return False
            if pre1 is None:
                return False
            if pre2 is None:
                return True
            k1 = pre_key(pre1)
            k2 = pre_key(pre2)
            for a, b in zip(k1, k2):
                if a != b:
                    return a < b
            return len(k1) < len(k2)

    return [w.v for w in sorted((Wrapper(v) for v in versions), key=__import__('functools').cmp_to_key(
        lambda a, b: -1 if a < b else (1 if b < a else 0)))]

